import React from "react";
import "./PetsCardsGrid.css"; // Import CSS
import EmotionalCard from "./EmotionalCard";
import CommunicationCard from "./CommunicationCard";
import ChildrenAndPetsCard from "./ChildrenAndPetsCard";
import HealthCard from "./HealthCard";

function CardsGrid() {
  return (
    <div className="cards-grid">
      <EmotionalCard />
      <CommunicationCard />
      <ChildrenAndPetsCard />
      <HealthCard />
    </div>
  );
}

export default CardsGrid;
